@* Displays a single task card with title, assignee, priority badge, due date, and move buttons *@

<div class="task-card">
    <div class="task-card-header">
        <span class="task-title">@Task.Title</span>
        <span class="priority-badge priority-@Task.Priority.ToLowerInvariant()">@Task.Priority</span>
    </div>
    <div class="task-card-body">
        <span class="task-assignee">👤 @Task.Assignee</span>
        <span class="task-due">📅 @Task.DueDate.ToString("MMM dd")</span>
    </div>
    <div class="task-card-actions">
        @if (ShowMoveLeft)
        {
            <button class="btn btn-sm btn-outline-secondary" @onclick="OnMoveLeftClick" disabled="@IsMoving">◀ Move Left</button>
        }
        @if (ShowMoveRight)
        {
            <button class="btn btn-sm btn-outline-secondary" @onclick="OnMoveRightClick" disabled="@IsMoving">Move Right ▶</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public TaskItem Task { get; set; } = default!;

    [Parameter]
    public bool ShowMoveLeft { get; set; }

    [Parameter]
    public bool ShowMoveRight { get; set; }

    [Parameter]
    public EventCallback<TaskItem> OnMoveLeft { get; set; }

    [Parameter]
    public EventCallback<TaskItem> OnMoveRight { get; set; }

    private bool IsMoving;

    private async System.Threading.Tasks.Task OnMoveLeftClick()
    {
        IsMoving = true;
        await OnMoveLeft.InvokeAsync(Task);
        IsMoving = false;
    }

    private async System.Threading.Tasks.Task OnMoveRightClick()
    {
        IsMoving = true;
        await OnMoveRight.InvokeAsync(Task);
        IsMoving = false;
    }
}

@* Inline form to create a new task within a column *@

<div class="add-task-form">
    <div class="mb-2">
        <input type="text" class="form-control form-control-sm" placeholder="Title" @bind="Title" />
    </div>
    <div class="mb-2">
        <input type="text" class="form-control form-control-sm" placeholder="Assignee" @bind="Assignee" />
    </div>
    <div class="mb-2">
        <select class="form-select form-select-sm" @bind="Priority">
            <option value="">-- Priority --</option>
            <option value="High">High</option>
            <option value="Medium">Medium</option>
            <option value="Low">Low</option>
        </select>
    </div>
    <div class="mb-2">
        <input type="date" class="form-control form-control-sm" @bind="DueDate" />
    </div>
    <div class="d-flex gap-2">
        <button class="btn btn-sm btn-primary" @onclick="HandleSave" disabled="@IsSaving">Save</button>
        <button class="btn btn-sm btn-secondary" @onclick="HandleCancel" disabled="@IsSaving">Cancel</button>
    </div>
    @if (!string.IsNullOrEmpty(validationError))
    {
        <div class="text-danger mt-1 small">@validationError</div>
    }
</div>

@code {
    [Parameter]
    public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate)> OnSave { get; set; }

    [Parameter]
    public EventCallback OnCancel { get; set; }

    private string Title = string.Empty;
    private string Assignee = string.Empty;
    private string Priority = string.Empty;
    private DateTime DueDate = DateTime.Today;
    private bool IsSaving;
    private string? validationError;

    private async Task HandleSave()
    {
        validationError = null;

        if (string.IsNullOrWhiteSpace(Title) || string.IsNullOrWhiteSpace(Assignee) || string.IsNullOrWhiteSpace(Priority))
        {
            validationError = "Title, assignee, and priority are required.";
            return;
        }

        IsSaving = true;
        await OnSave.InvokeAsync((Title, Assignee, Priority, DueDate));
        IsSaving = false;
        ResetForm();
    }

    private async Task HandleCancel()
    {
        ResetForm();
        await OnCancel.InvokeAsync();
    }

    private void ResetForm()
    {
        Title = string.Empty;
        Assignee = string.Empty;
        Priority = string.Empty;
        DueDate = DateTime.Today;
        validationError = null;
    }
}

@* Summary stats bar showing total, per-column, and overdue task counts *@

<div class="board-stats d-flex flex-wrap gap-3 mb-3 p-3 bg-light rounded">
    <span class="badge bg-dark fs-6">Total: @Tasks.Count</span>
    <span class="badge bg-info fs-6">To Do: @Tasks.Count(t => t.Status == "To Do")</span>
    <span class="badge bg-warning text-dark fs-6">In Progress: @Tasks.Count(t => t.Status == "In Progress")</span>
    <span class="badge bg-success fs-6">Done: @Tasks.Count(t => t.Status == "Done")</span>
    <span class="badge bg-danger fs-6">Overdue: @Tasks.Count(t => t.DueDate < DateTime.Today)</span>
</div>

@code {
    [Parameter, EditorRequired]
    public List<TaskItem> Tasks { get; set; } = new();
}

@* Search bar for filtering tasks by title *@

<div class="mb-3">
    <input type="text"
           class="form-control"
           placeholder="Search tasks by title..."
           value="@SearchText"
           @oninput="HandleInput" />
</div>

@code {
    [Parameter]
    public string SearchText { get; set; } = string.Empty;

    [Parameter]
    public EventCallback<string> OnSearchChanged { get; set; }

    private async Task HandleInput(ChangeEventArgs e)
    {
        var value = e.Value?.ToString() ?? string.Empty;
        await OnSearchChanged.InvokeAsync(value);
    }
}

@* A single Kanban column displaying its tasks and an add-task form *@

<div class="board-column">
    <div class="board-column-header d-flex justify-content-between align-items-center mb-2 p-2 rounded">
        <h5 class="mb-0">@ColumnName</h5>
        <span class="badge bg-secondary">@Tasks.Count</span>
    </div>

    <div class="board-column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      ShowMoveLeft="ShowMoveLeft"
                      ShowMoveRight="ShowMoveRight"
                      OnMoveLeft="HandleMoveLeft"
                      OnMoveRight="HandleMoveRight" />
        }
    </div>

    @if (showAddForm)
    {
        <AddTaskForm OnSave="HandleSave" OnCancel="HandleCancel" />
    }
    else
    {
        <button class="btn btn-sm btn-outline-primary w-100 mt-2" @onclick="() => showAddForm = true">+ Add Task</button>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public string ColumnName { get; set; } = string.Empty;

    [Parameter, EditorRequired]
    public List<TaskItem> Tasks { get; set; } = new();

    [Parameter]
    public bool ShowMoveLeft { get; set; }

    [Parameter]
    public bool ShowMoveRight { get; set; }

    [Parameter]
    public EventCallback<TaskItem> OnMoveLeft { get; set; }

    [Parameter]
    public EventCallback<TaskItem> OnMoveRight { get; set; }

    [Parameter]
    public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate)> OnTaskCreated { get; set; }

    private bool showAddForm;

    private async Task HandleMoveLeft(TaskItem task) => await OnMoveLeft.InvokeAsync(task);
    private async Task HandleMoveRight(TaskItem task) => await OnMoveRight.InvokeAsync(task);

    private async Task HandleSave((string Title, string Assignee, string Priority, DateTime DueDate) formData)
    {
        await OnTaskCreated.InvokeAsync(formData);
        showAddForm = false;
    }

    private void HandleCancel() => showAddForm = false;
}

